Fixpoint noblob (e : expr) : bool :=
  match e with
  | ELit _ | EVar _ => true
  | EAlu _ a b | EAluw _ a b | EMd _ a b | EMdw _ a b => noblob a && noblob b
  | EExt _ _ _ a => noblob a
  | EBlob _ _ _ _ => false
  end%bool.
Definition eval_at (J : nat) (e : expr) (v : Z) : option Z := ltac2:(Rpl.RP.run_k (rplG ()) 3 "S0;LJ;Ri1;Le;Ri18;Lv;Ri2;Ee';RA3;k118;r3;A1;o70;r1;r2;i18;m36;RNL~Ri36;A1;i45;i2;A2;k37;A2;k38;o160;r1;A1;k216;r1;2;A2;o47;i2;A2;k3;A1;o4;Y6;00;A2;k21;k217;r1;A1;o51;i2;").
Fixpoint eval_all (fuel : nat) (J : nat) (e : expr) (v : Z) (c : Z) : bool :=
  match fuel with
  | O => true
  | S f => match eval_at J e v with Some c' => Z.eqb c' c && eval_all f J e (v + 1) c | None => false end
  end%bool.
Definition evalreg (ss : sym_state) (r J : nat) : option sym_state := ltac2:(Rpl.RP.run_k (rplG ()) 3 "S9;A1;i45;i44;A1;o51;i44;A2;i69;i2;i2;A1;i45;i2;A1;k120;r4;A1;o51;i2;A1;o70;r1;A1;o49;i76;A1;o51;i78;Lss;Ri44;Lr;Ri1;LJ;Ri1;m36;RNL~Ri36;#0;A1;k138;A2;k37;A2;k145;o160;r2;A2;k145;r2;N32;2;#1;Ee;RA2;k197;r3;r2;i18;m45;RNLx;RA1;i45;i2;#0;m45;RNLx;RA1;i45;#2;#3;A2;k151;#4;r1;2;Lp;R#2;m69;RNLp;RA2;i69;i2;i2;#3;r1;1;Lc;Ri2;Lc';Ri2;m36;RNL~Ri36;#3;A2;k175;r2;r1;2;A2;o47;i2;r2;#5;#5;2;Lc;Ri2;A2;o47;i44;A6;o73;A1;k74;r5;A3;k218;A1;k75;r5;r4;#6;#7;A1;k120;r5;A1;k77;r5;#8;m45;RNLx;RA1;i45;#2;#0;A2;k151;#4;A1;o123;r2;2;Lp;R#2;m69;RNLp;RA2;i69;i2;i2;#0;r1;1;Llo;Ri2;Lhi;Ri2;m36;RNL~Ri36;#0;A1;k138;A2;k37;A2;k127;r2;r1;A2;k127;A2;k15;r1;r2;k219;2;#1;m45;RNLx;RA1;i45;i2;#0;A3;k220;r5;r4;r2;2;Lc;Ri2;m36;RNL~Ri36;#0;A5;k221;A1;k7;A2;k27;A2;k15;r2;r3;A1;o28;o104;r6;r5;r3;r1;2;A2;o47;i44;A6;o73;A1;k74;r8;A3;k218;A1;k75;r8;r7;#6;#7;A1;k120;r8;A1;k77;r8;#8;#1;#1;#1;").

Fixpoint eval_all_in (fuel : nat) (J : nat) (e : expr) (v : Z) (lo hi : Z) : bool :=
  match fuel with
  | O => true
